// AUTOSAVE_INTERVAL is defined before snippets run, so the editors' settings are changed instead.
add_filter( 'block_editor_settings_all', 'perfectpixel_autosave_interval_block' );
add_action( 'admin_enqueue_scripts', 'perfectpixel_autosave_interval_classic', 999 );

function perfectpixel_autosave_interval_value() {
	return max( 10, (int) '{{autosave_interval_seconds}}' );
}

function perfectpixel_autosave_interval_block( $settings ) {
	$settings['autosaveInterval'] = perfectpixel_autosave_interval_value();
	return $settings;
}

function perfectpixel_autosave_interval_classic() {
	$scripts = wp_scripts();
	$data    = $scripts->get_data( 'autosave', 'data' );
	if ( is_string( $data ) && '' !== $data ) {
		$scripts->add_data( 'autosave', 'data', preg_replace( '/"autosaveInterval":\s*"?\d+"?/', '"autosaveInterval":' . perfectpixel_autosave_interval_value(), $data ) );
	}
}
